// Writes engine/clutch.js: the precomputed motor-clutch table plus a bilinear lookup.
const fs = require('fs');
const T = JSON.parse(fs.readFileSync(__dirname + '/../engine/clutch-table.json', 'utf8'));
const src = `/*
 * Motor-clutch growth-cone traction (generated by tools/clutch-table.js + tools/emit-clutch.js).
 * Table of mean traction (pN) and retrograde actin flow (nm/s) from a stochastic motor-clutch
 * simulation (Chan & Odde 2008 parameters) over substrate spring constant (log10 pN/nm) and
 * clutch binding-rate scale (ligand density x receptor level). Regenerate with other motor or
 * clutch numbers by editing tools/clutch-table.js.
 */
(function (root, factory) {
  const mod = factory();
  if (typeof module === 'object' && module.exports) module.exports = mod;
  else { root.NE2 = root.NE2 || {}; Object.assign(root.NE2, mod); }
})(typeof self !== 'undefined' ? self : this, function () {
  'use strict';
  const TABLE = ${JSON.stringify(T)};
  const LK = TABLE.logKsub, ON = TABLE.onScale, F = TABLE.traction, V = TABLE.flow;
  const FMAX = Math.max(...F.map((r) => Math.max(...r)));
  // substrate Young's modulus (kPa) -> clutch-scale spring constant (pN/nm), adhesion radius ~100 nm
  const kSubFromKPa = (E) => 0.14 * E;
  const L0 = LK[0], LS = LK[1] - LK[0], NL = LK.length - 1;   // uniform log-stiffness axis
  let lastE = -1, lastI = 0, lastTi = 0;
  function lookup(EkPa, onScale, out) {
    let i = lastI, ti = lastTi;
    if (EkPa !== lastE) {
      const x = (Math.log10(Math.max(1e-6, kSubFromKPa(EkPa))) - L0) / LS;
      if (x <= 0) { i = 0; ti = 0; } else if (x >= NL) { i = NL - 1; ti = 1; } else { i = x | 0; ti = x - i; }
      lastE = EkPa; lastI = i; lastTi = ti;
    }
    let j = 0, tj = 0;
    if (onScale <= ON[0]) { j = 0; tj = 0; } else if (onScale >= ON[ON.length - 1]) { j = ON.length - 2; tj = 1; }
    else { while (ON[j + 1] < onScale) j++; tj = (onScale - ON[j]) / (ON[j + 1] - ON[j]); }
    const F0 = F[j], F1 = F[j + 1], V0 = V[j], V1 = V[j + 1], a = 1 - ti, b = 1 - tj;
    out[0] = (F0[i] * a + F0[i + 1] * ti) * b + (F1[i] * a + F1[i + 1] * ti) * tj;
    out[1] = (V0[i] * a + V0[i + 1] * ti) * b + (V1[i] * a + V1[i + 1] * ti) * tj;
    return out;
  }
  return { Clutch: { TABLE, lookup, FMAX, VU: TABLE.params.vu, kSubFromKPa } };
});
`;
fs.writeFileSync(__dirname + '/../engine/clutch.js', src);
console.log('wrote clutch.js', src.length);
